/**
 * Build a localStorage key that is isolated to one server workspace.
 *
 * The workspace id is generated by the local server from the invocation
 * directory. Keeping it out of the human-readable key also avoids exposing
 * the absolute directory path in browser storage inspection tools.
 */
export function createWorkspaceStorageKey(baseKey, workspaceId) {
  const normalizedBaseKey = String(baseKey || '').trim()
  const normalizedWorkspaceId = String(workspaceId || '').trim()
  if (!normalizedBaseKey || !normalizedWorkspaceId) return null

  return `${normalizedBaseKey}.${encodeURIComponent(normalizedWorkspaceId)}`
}
